 async function saveStudentTc(studentId,tc){const clean=String(tc||'').replace(/\D/g,'');if(!clean)return null;if(clean.length!==11)return {message:'T.C. Kimlik No 11 haneli olmalıdır.'};const {error}=await supabase.rpc('set_student_national_id',{p_student:studentId,p_tc:clean});if(error)return error;const {data:check,error:checkError}=await supabase.rpc('student_tc_status',{p_student:studentId});if(checkError)return checkError;if(!check?.is_set||check?.last4!==clean.slice(-4))return {message:'T.C. Kimlik No veritabanında doğrulanamadı.'};return null}
