 async function saveAttendance(){if(!attendanceClass)return;const list=students.filter(s=>s.class_id===attendanceClass);const payload=list.map(s=>({student_id:s.id,class_id:attendanceClass,recorded_by:session.user.id,attendance_date:attendanceDate,status:attendanceRows[s.id]?.status||'present',note:attendanceRows[s.id]?.note||null}));setBusy(true);const {error}=await supabase.from('attendance').upsert(payload,{onConflict:'student_id,attendance_date'});setBusy(false);if(error)return setMsg(error.message);setMsg(`${list.length} öğrencinin yoklaması kaydedildi.`);await loadAttendance()}

